// Server-side content layer for the Achala IT Solutions website.
// Content JSON is generated by scripts/achalasolutions/dqs_site_export.py into src/content/.
import fs from "node:fs";
import path from "node:path";
import type { DashWidget } from "@/components/site/DashWidgets";

export type Crumb = { name: string; url: string | null };

export type Card = { title: string; url: string; tag: string; desc: string };

export type Block =
  | { t: "hero"; x: string }
  | { t: "p"; x: string }
  | { t: "h2"; x: string; sub?: string }
  | { t: "h3"; x: string; sub?: string }
  | { t: "bullets"; items: [string, string][] }
  | { t: "table"; caption?: string; headers: string[]; rows: string[][] }
  | { t: "note"; x: string; variant?: "insight" | "compliance" | "warning" | "success" }
  | { t: "diagram"; kind: string; title?: string; labels?: string[]; note?: string }
  | {
      t: "arch";
      title: string;
      lanes: string[];
      badges?: { label: string; value: string }[];
      nodes: { id: string; lane: number; label: string; sub?: string; hot?: boolean }[];
      edges: { a: string; b: string; label?: string }[];
      note?: string;
    }
  | {
      t: "chart";
      title: string;
      variant?:
        | "line"
        | "bar"
        | "radar"
        | "area"
        | "donut"
        | "funnel"
        | "heatmap"
        | "gauge"
        | "network";
      cats: string[];
      series: { name: string; points: number[] }[];
      unit?: string;
      yMax?: number;
      nodes?: { id: string; x: number; y: number; hub?: boolean; label: string }[];
      links?: [number, number][];
      note?: string;
      caption?: string;
    }
  | {
      t: "explorer";
      title: string;
      intro: string;
      service: string;
      practiceNote?: string;
      industries: {
        slug: string;
        name: string;
        flagship: boolean;
        hook: string;
        plays: string[];
        systems?: string[];
        evidence?: { title: string; url: string }[];
        kpis: { label: string; value: string }[];
        capUrl: string;
      }[];
    }
  | {
      t: "dash";
      title: string;
      kpis: { label: string; value: string; delta?: string; dir?: "up" | "down" | "flat" }[];
      gates?: { name: string; pct: number }[];
      log?: { t: string; msg: string; tag: string }[];
      note?: string;
    }
  | {
      t: "idash";
      title: string;
      badge?: string;
      note?: string;
      kpis: { label: string; value: string; delta?: string; dir?: "up" | "down" | "flat"; spark?: number[] }[];
      tabs: { name: string; widgets: DashWidget[] }[];
    }
  | { t: "cta"; x: string };

export type PageData = {
  id: string;
  title: string;
  url: string;
  template: string;
  breadcrumb: string;
  seo_title: string;
  meta_description: string;
  blocks: Block[];
  words: number;
  section: string;
  l1: string;
  l2: string;
  l3: string;
  l4: string;
  crumbs: Crumb[];
  related: Card[];
  cards: Card[];
  evidence?: { title: string; url: string; ind: string }[];
  hero_chip?: { head: string; sub: string };
  extras?: HomeExtras;
  profile?: { role: string; name: string; focus: string[]; placeholder: boolean };
  partner?: { name: string; focus: string; scenarios: string[] };
  published?: string;
};

export type HomeExtras = {
  stats: { value: string; label: string }[];
  domains: { name: string; url: string; desc: string; metric?: string; plat?: string; start?: boolean }[];
  industries: { name: string; url: string }[];
  cases: { title: string; url: string; desc: string; tag: string }[];
  insights: { title: string; url: string; desc: string; tag: string }[];
  platforms: { name: string; url: string; desc: string }[];
};

export type NavCol = { label: string; url: string; children: NavCol[] };
export type NavItem = { label: string; url: string; mega: NavCol[] | null; wide?: boolean };
export type Nav = { primary: NavItem[]; cta: { label: string; url: string } };
export type FooterCol = { title: string; links: NavCol[] };

export type Brand = {
  name: string;
  legalName: string;
  tagline: string;
  positioning: string;
  promise: string;
  stats: { value: string; label: string }[];
  credentials: string[];
  offices: { title: string; city: string; desc: string }[];
  emails: { general: string; press: string; careers: string };
  site: string;
};

export type IndexRow = {
  url: string;
  file: string;
  title: string;
  template: string;
  section: string;
  l1: string;
  l2: string;
  l3: string;
  l4: string;
  seoTitle: string;
  metaDescription: string;
  words: number;
};

const CONTENT_DIR = path.join(process.cwd(), "src", "content");

let _index: IndexRow[] | null = null;
let _indexMtime = 0;
let _nav: { nav: Nav; footer: FooterCol[] } | null = null;
let _navMtime = 0;
let _brand: Brand | null = null;
let _brandMtime = 0;

function readJson<T>(file: string, mtimeRef: { v: number }): T {
  const full = path.join(CONTENT_DIR, file);
  const mtime = fs.statSync(full).mtimeMs;
  if (mtimeRef.v !== mtime) {
    mtimeRef.v = mtime;
  }
  return JSON.parse(fs.readFileSync(full, "utf8")) as T;
}

export function pageIndex(): IndexRow[] {
  if (!_index) {
    const f = path.join(CONTENT_DIR, "index.json");
    _indexMtime = fs.statSync(f).mtimeMs;
    _index = JSON.parse(fs.readFileSync(f, "utf8"));
  } else {
    const f = path.join(CONTENT_DIR, "index.json");
    const mtime = fs.statSync(f).mtimeMs;
    if (mtime !== _indexMtime) {
      _indexMtime = mtime;
      _index = JSON.parse(fs.readFileSync(f, "utf8"));
    }
  }
  return _index;
}

export function navData(): { nav: Nav; footer: FooterCol[] } {
  if (!_nav) {
    const f = path.join(CONTENT_DIR, "nav.json");
    _navMtime = fs.statSync(f).mtimeMs;
    _nav = JSON.parse(fs.readFileSync(f, "utf8"));
  } else {
    const f = path.join(CONTENT_DIR, "nav.json");
    const mtime = fs.statSync(f).mtimeMs;
    if (mtime !== _navMtime) {
      _navMtime = mtime;
      _nav = JSON.parse(fs.readFileSync(f, "utf8"));
    }
  }
  return _nav;
}

export function brandData(): Brand {
  if (!_brand) {
    const f = path.join(CONTENT_DIR, "brand.json");
    _brandMtime = fs.statSync(f).mtimeMs;
    _brand = JSON.parse(fs.readFileSync(f, "utf8"));
  } else {
    const f = path.join(CONTENT_DIR, "brand.json");
    const mtime = fs.statSync(f).mtimeMs;
    if (mtime !== _brandMtime) {
      _brandMtime = mtime;
      _brand = JSON.parse(fs.readFileSync(f, "utf8"));
    }
  }
  return _brand;
}

export function fileForUrl(urlPath: string): string | null {
  const rows = pageIndex();
  const hit = rows.find((r) => r.url === urlPath);
  return hit ? hit.file : null;
}

export function readPage(file: string): PageData | null {
  try {
    const raw = fs.readFileSync(path.join(CONTENT_DIR, "pages", `${file}.json`), "utf8");
    return JSON.parse(raw) as PageData;
  } catch {
    return null;
  }
}

export function urlToSlugSegments(urlPath: string): string[] {
  return urlPath.replace(/^\//, "").replace(/\/$/, "").split("/").filter(Boolean);
}
